  <div class="panel card">
    {% if b.kind == 'existing_thesis' %}
      {%- set p = v.pillar(b.pillar_id) -%}
      <h3><a href="/suggestion/{{ s.id }}">{{ b.pillar_id }}</a>
        <span class="pill {{ b.stance }}">{{ b.stance }}</span>
        <span class="pill">strength {{ b.strength }}</span>
        {% if b.wrong_if_met %}<span class="pill contradicts">"wrong if" met</span>{% endif %}
        {% if s.second_look %}<span class="pill second">second look</span>{% endif %}
        <span class="muted small">{{ v.thesis(v.ticker_of(s)).stance }} · {{ sizes.get(v.ticker_of(s)) }} bps</span></h3>
      {% if p %}<div class="small muted">{{ p.statement }}</div>{% endif %}
      {% for a in b.assumptions %}
        <div class="small">Stated {{ a.driver_id }}: <b>{{ a.stated_value | num }}</b>
          (book {{ v.driver(a.driver_id).analyst | num if v.driver(a.driver_id) else a.book_value | num }},
          consensus {{ a.consensus_value | num }})</div>
      {% endfor %}
    {% elif b.kind == 'new_thesis' %}
      <h3><a href="/suggestion/{{ s.id }}">New thesis for {{ b.ticker }}</a>
        {% if s.second_look %}<span class="pill second">second look</span>{% endif %}</h3>
      <div>{{ b.statement }}</div>
      <div class="small muted">Wrong if: {{ b.wrong_if }}</div>
    {% else %}
      <h3><a href="/suggestion/{{ s.id }}">Conviction review: {{ b.ticker }}</a></h3>
      <div class="small">Accepted contradicting evidence on {{ b.pillar_id }} reached the review threshold.</div>
    {% endif %}
    <div>{{ s.rationale }}</div>
    <div class="small">Linked emails:
      {% for eid in v.sections(s) | map(attribute='email_id') | unique %}{{ email_link(v, eid) }}{% if not loop.last %}; {% endif %}{% endfor %}
    </div>
    {{ actions(v, s, v.status(s)) }}
  </div>
{%- endmacro %}

{% macro projection_table(projections) -%}
  <table>
    <tr><th></th>{% for k in projections %}<th class="num">{{ k }}</th>{% endfor %}</tr>
    <tr><td>Revenue ($bn)</td>{% for p in projections.values() %}<td class="num">{{ p.revenue_usd_bn | num }}</td>{% endfor %}</tr>
