    <tr><td>Operating income ($bn)</td>{% for p in projections.values() %}<td class="num">{{ p.operating_income_usd_bn | num }}</td>{% endfor %}</tr>
    <tr><td>EPS ($)</td>{% for p in projections.values() %}<td class="num eps">{{ p.eps | num(2) }}</td>{% endfor %}</tr>
    <tr><td>Target price ($)</td>{% for p in projections.values() %}<td class="num">{{ p.target_price | num(0) }}</td>{% endfor %}</tr>
  </table>
{%- endmacro %}
EOF
