{% extends "base.html" %}
{% from "macros.html" import actions, email_link %}
{% block title %}{{ s.id }}{% endblock %}
{% block content %}
{% set b = s.body %}
<p class="small"><a href="/">← Brief</a> · <a href="/company/{{ ticker }}">{{ ticker }}</a></p>
<h1>{{ s.id }}</h1>
<div class="grid2">
