    <h3>Change to {{ b.pillar_id }}
      <span class="pill {{ b.stance }}">{{ b.stance }}</span> <span class="pill">strength {{ b.strength }}</span>
      {% if b.wrong_if_met %}<span class="pill contradicts">"wrong if" met</span>{% endif %}
      {% if s.second_look %}<span class="pill second">second look</span>{% endif %}</h3>
    {% if p %}<div>{{ p.statement }}</div><div class="small muted">Wrong if: {{ p.wrong_if }}</div>{% endif %}
  {% elif b.kind == 'new_thesis' %}
    <h3>New thesis candidate for {{ b.ticker }}</h3>
    <div>{{ b.statement }}</div>
    <div class="small muted">Wrong if: {{ b.wrong_if }}</div>
    <div class="small">Linked drivers: {{ b.driver_ids | join(', ') or 'none' }}</div>
  {% else %}
    <h3>Conviction review for {{ b.ticker }}</h3>
    <div>Current conviction: <b>{{ v.thesis(b.ticker).conviction }}</b> of 5. Pick a value, or dismiss the review. The app never proposes one.</div>
  {% endif %}
    <p>{{ s.rationale }}</p>
    {% if s.status == 'rejected' %}<div class="flash err">Rejected in validation: {{ s.reject_reason }}</div>{% endif %}
    {{ actions(v, s, status) }}
  </div>

  {% if b.kind == 'existing_thesis' and status == 'open' %}
  <details class="panel"><summary>Edit strength, then accept</summary>
    <form method="post" action="/suggestion/{{ s.id }}/edit" hx-post="/suggestion/{{ s.id }}/edit" hx-target="#flash">
      <label>Strength <select name="strength">{% for n in [1, 2, 3] %}<option value="{{ n }}" {% if n == b.strength %}selected{% endif %}>{{ n }}</option>{% endfor %}</select></label>
      <button class="primary">Accept with this strength</button>
    </form></details>
  {% elif b.kind == 'new_thesis' and status == 'open' %}
  <details class="panel"><summary>Edit wording, then accept</summary>
    <form method="post" action="/suggestion/{{ s.id }}/edit" hx-post="/suggestion/{{ s.id }}/edit" hx-target="#flash">
      <label>Statement<textarea name="statement" rows="3">{{ b.statement }}</textarea></label>
      <label>Wrong if<textarea name="wrong_if" rows="2">{{ b.wrong_if }}</textarea></label>
      <button class="primary">Accept as edited</button>
    </form></details>
  {% elif b.kind == 'conviction_review' and status == 'open' %}
  <div class="panel">
    <form method="post" action="/conviction/{{ b.ticker }}" hx-post="/conviction/{{ b.ticker }}" hx-target="#flash">
      <input type="hidden" name="suggestion_id" value="{{ s.id }}">
      <label>Conviction <select name="conviction"><option value="" disabled selected>pick</option>{% for n in range(1, 6) %}<option value="{{ n }}">{{ n }}</option>{% endfor %}</select></label>
      <button class="primary">Set conviction</button>
    </form>
  </div>
  {% endif %}

  {% if b.kind == 'existing_thesis' %}
    {% for a in b.assumptions %}
      {% set d = v.driver(a.driver_id) %}
      {% set eff = v.effect(a.driver_id, a.stated_value) %}
      <div class="panel" id="driver-{{ a.driver_id | replace('.', '-') }}">
        <h3>Linked assumption: {{ d.label if d else a.driver_id }}</h3>
        <table>
          <tr><th>Stated in the email</th><th class="num">Book now</th><th class="num">Consensus</th><th>Unit</th></tr>
          <tr><td class="num"><b>{{ a.stated_value | num }}</b></td><td class="num book-value">{{ d.analyst | num if d else '' }}</td>
              <td class="num">{{ a.consensus_value | num }}</td><td>{{ d.unit if d else '' }}</td></tr>
        </table>
        {% if eff %}
        <div class="small">Effect if the book took the stated figure:
          EPS {{ eff['now'].eps | num(2) }} → <b>{{ eff['if'].eps | num(2) }}</b>,
          target price {{ eff['now'].target_price | num(0) }} → <b>{{ eff['if'].target_price | num(0) }}</b>
          {% if d and d.unit == 'usd_bn' %}<span class="muted">(capex does not feed EPS)</span>{% endif %}</div>
        {% endif %}
        <form class="actions" method="post" action="/driver/{{ a.driver_id }}" hx-post="/driver/{{ a.driver_id }}"
              hx-target="#driver-{{ a.driver_id | replace('.', '-') }}" hx-swap="beforeend">
          <input type="hidden" name="suggestion_id" value="{{ s.id }}">
          <input type="number" step="any" name="value" value="{{ a.stated_value }}" min="{{ d.min if d else '' }}" max="{{ d.max if d else '' }}">
          <button>Update the assumption</button>
        </form>
      </div>
    {% endfor %}
  {% endif %}

  {% if siblings %}<div class="panel small">Opposite stance on the same pillar:
    {% for x in siblings %}<a href="/suggestion/{{ x.id }}">{{ x.id }}</a>{% endfor %}</div>{% endif %}

  {% if b.kind != 'conviction_review' %}
  <div class="panel" id="verify">
    <form method="post" action="/suggestion/{{ s.id }}/verify" hx-post="/suggestion/{{ s.id }}/verify" hx-target="#verify-out">
      <button>Verify against filings and the change log</button></form>
    <div id="verify-out">{% if verify %}{% include "fragments/verify.html" %}{% endif %}</div>
  </div>
  {% endif %}
</section>

<section>
  <h2>Linked emails</h2>
  {% for eid, quotes in linked.items() %}
    {% set e = v.email(eid) %}
    <div class="panel">
      <h3>{{ email_link(v, eid) }}</h3>
      {% if e and not v.quarantined(eid) %}
        {% for q in quotes %}<blockquote>{{ q }}</blockquote>{% endfor %}
        <details><summary class="small">Whole email, quotes highlighted</summary>
          <div class="body">{{ highlight(e.body, quotes) }}</div></details>
      {% endif %}
    </div>
  {% else %}<p class="muted">No linked emails.</p>{% endfor %}
</section>
</div>
{% endblock %}
EOF
echo ok

