    {% for s in trace.suggestions %}<p>Suggestion: <a href="/suggestion/{{ trace.email_id }}.{{ s.id }}">{{ s.id }}</a> · {{ s.rationale }}</p>{% endfor %}
    {% for s in trace.rejected %}<p class="small muted">Rejected {{ s.id }}: {{ s.reject_reason }}</p>{% endfor %}
    {% if trace.analysis and trace.analysis.no_change_reason %}<p class="small">No change: {{ trace.analysis.no_change_reason }}</p>{% endif %}
    {% if trace.note or trace.suggestions %}<p class="small"><a href="/">Added to your brief →</a></p>{% endif %}
